window.MIDTERM_QUESTIONS=[{"id": "midterm-vize-2023-front-q1", "lesson": 103, "text": "Aşağıdakilerden hangisi açık kaynak kodlu yazılımlara örnek verilemez?", "options": ["FAUmachine", "SheepShaver", "VirtualBox", "Trango", "KVM"], "answer": 3, "correctIndices": [3], "explanation": "Notların açık kaynak/ticari sanal makine yazılımları listesinde Trango ticari gruptadır. ", "sourceLabel": "Gösterilen kaynak: 2023 Güz Vize · B Grubu · Soru 1"}, {"id": "midterm-vize-2023-front-q2", "lesson": 101, "text": "Aşağıdakilerden hangisi bulut bilişimin temel özelliklerinden değildir?", "options": ["Kişiselleştirme", "Paylaşım ve işbirliği", "Düşük Maliyet", "Erişim Kolaylığı", "Esnek olmayan ödeme"], "answer": 4, "correctIndices": [4], "explanation": "Bulutun anlatılan avantajı esnek ödeme/kullanım ilişkisidir; esnek olmayan ödeme bu listeye uymaz. ", "sourceLabel": "Gösterilen kaynak: 2023 Güz Vize · B Grubu · Soru 2 | Diğer kaynaklar: 2023 Final · B Grubu · arka sayfa · Soru 21. Şıklar gösterilen kaynağa aittir."}, {"id": "midterm-vize-2023-front-q3", "lesson": 101, "text": "Aşağıdakilerden hangisi bulut bilişimin temel unsurlarından değildir?", "options": ["Geniş ağ erişimi", "Çabukluk ve esneklik", "Ortak kaynak havuzu", "Ölçülebilir hizmeti", "Network havuzu"], "answer": 4, "correctIndices": [4], "explanation": "Kaynak havuzu temel unsurdur; “network havuzu” adıyla ayrı altıncı NIST unsuru yoktur. ", "sourceLabel": "Gösterilen kaynak: 2023 Güz Vize · B Grubu · Soru 3 | Diğer kaynaklar: 2022 Final · B Grubu · arka sayfa · Soru 21. Şıklar gösterilen kaynağa aittir."}, {"id": "midterm-vize-2023-front-q4", "lesson": 101, "text": "I. İnternet\nII. Kişisel Bilgisayar\nIII. Bilgisayar Ağları\nIV. Ana Bilgisayar\nBulut bilişim gelişim sırası aşağıdaki şıklardan hangisinde doğru verilmiştir?", "options": ["I, II, III, IV", "IV, II, III, I", "II, I, III, IV", "IV, III, II, I", "II, I, IV, III"], "answer": 1, "correctIndices": [1], "explanation": "Dersin sade tarihsel sıralaması: ana bilgisayar → kişisel bilgisayar → bilgisayar ağları → internet. Bu, dersin pedagojik gelişim dizisidir; teknolojilerin tarihleri birbirleriyle örtüşür.", "sourceLabel": "Gösterilen kaynak: 2023 Güz Vize · B Grubu · Soru 4 | Diğer kaynaklar: 2024 Güz Vize · B Grubu · Soru 2. Şıklar gösterilen kaynağa aittir."}, {"id": "midterm-vize-2023-front-q5", "lesson": 101, "text": "Bulut bilişimin bileşenlerinden değildir?", "options": ["Tüketici", "Servis Sağlayıcı", "Servis Geliştirici", "Servis Yayan"], "answer": 3, "correctIndices": [3], "explanation": "Notlardaki üç temel paydaş tüketici, servis sağlayıcı ve servis geliştiricidir. ", "sourceLabel": "Gösterilen kaynak: 2023 Güz Vize · B Grubu · Soru 5"}, {"id": "midterm-vize-2023-front-q6", "lesson": 102, "text": "Bir kuruluşun kendi bünyesinde barındırıp yönettiği kaynaklarla, harici altyapı kaynaklarının birleştirilmesi sonucu oluşan bulut modeli hangisidir?", "options": ["Genel Bulut", "Özel Bulut", "Hibrit Bulut", "Topluluk Bulut", "Şirket Bulut"], "answer": 2, "correctIndices": [2], "explanation": "Kurum içi/özel kaynaklarla dış bulut kaynaklarının bütünleştirilmesi hibrit bulut yaklaşımıdır. ", "sourceLabel": "Gösterilen kaynak: 2023 Güz Vize · B Grubu · Soru 6 | Diğer kaynaklar: 2024 Güz Vize · B Grubu · Soru 11. Şıklar gösterilen kaynağa aittir."}, {"id": "midterm-vize-2023-front-q7", "lesson": 101, "text": "Aşağıdakilerden hangisi bulut bilişimin dezavantajlarından değildir?", "options": ["Performans sorunu", "Satıcı kilidi", "Yönetilebilirlik", "Planlı ve Plansız Kesintiler", "Sistem Güncellemeleri"], "answer": 2, "correctIndices": [2], "explanation": "Yönetilebilirlik avantaj olarak ele alınmıştır. Diğerleri performans, bağımlılık, kesinti veya uyumluluk riski doğurabilir. Fotoğrafın sol kenarı bazı satır başlarını kesiyor. A, D ve soru başı bağlam ve görünen harflerden tamamlandı; belirsiz bölüm kaynak görüntüde görülebilir.", "sourceLabel": "Gösterilen kaynak: 2023 Güz Vize · B Grubu · Soru 7"}, {"id": "midterm-vize-2023-front-q8", "lesson": 101, "text": "Çalışma notlarına göre ilk bulut uygulamasını yapan firma hangisidir?", "options": ["Amazon", "Microsoft", "Google", "Sun", "Oracle"], "answer": 0, "correctIndices": [0], "explanation": "Notlar Amazon’un S3 hizmetini 2006’da bulut gelişimindeki öncü örnek olarak anlatır; soru “çalışma notlarına göre” sorulduğu için A beklenir. Bulut fikrinin tarihsel kökleri daha eskidir; ilk bulut uygulaması hakkında evrensel tek tanım değildir.", "sourceLabel": "Gösterilen kaynak: 2023 Güz Vize · B Grubu · Soru 8"}, {"id": "midterm-vize-2023-front-q9", "lesson": 102, "text": "Servis sağlayıcı tarafından müşteriye kendi uygulamasını geliştirip, çalıştırabileceği bir platform ile tamamlayıcı servislerin ve gerekli teknolojik altyapının sunulmasına aşağıdakilerden hangisi denir?", "options": ["Servis Olarak Platform (PaaS)", "Servis Olarak Yazılım (SaaS)", "Servis Olarak Altyapı (IaaS)", "Servis Olarak Ortak (IaaO)", "Servis Olarak Ağ (IaaA)"], "answer": 0, "correctIndices": [0], "explanation": "Müşteriye uygulama geliştirme ve çalıştırma ortamı sunulması PaaS’tır. ", "sourceLabel": "Gösterilen kaynak: 2023 Güz Vize · B Grubu · Soru 9"}, {"id": "midterm-vize-2023-front-q10", "lesson": 102, "text": "Müşterinin ihtiyaç duyduğu temel bilişim kaynaklarını (işlemci, depolama, ağ kaynağı vb.) kendisinin yapılandırabilmesi ve bunların üzerine ihtiyacı olan işletim sistemi ve uygulamaları kurabilmesine aşağıdakilerden hangisi denir?", "options": ["Servis Olarak Platform (PaaS)", "Servis Olarak Yazılım (SaaS)", "Servis Olarak Altyapı (IaaS)", "Servis Olarak Ortak (IaaO)", "Servis Olarak Ağ (IaaA)"], "answer": 2, "correctIndices": [2], "explanation": "İşletim sistemi ve uygulama üzerinde müşteri yönetimiyle altyapı kaynaklarını sunan model IaaS’tır. ", "sourceLabel": "Gösterilen kaynak: 2023 Güz Vize · B Grubu · Soru 10 | Diğer kaynaklar: 2022 Final · B Grubu · arka sayfa · Soru 23 / 2023 Final · B Grubu · arka sayfa · Soru 13. Şıklar gösterilen kaynağa aittir."}, {"id": "midterm-vize-2023-front-q11", "lesson": 102, "text": "Müşterilerin uygulamaları ve verileri aynı bulut sağlayıcısını kullanan farklı müşterilerden gizlenmiş olsa da sağlanan hizmet ve donanımın ortak olarak müşteriler arasında kullanılmasına aşağıdakilerden hangisi denir?", "options": ["Genel Bulut", "Özel Bulut", "Hibrit Bulut", "Topluluk Bulut", "Şirket Bulut"], "answer": 0, "correctIndices": [0], "explanation": "Geniş müşteri kitlesine ortak altyapı üzerinden, kiracıları izole ederek hizmet sunma genel bulut örneğidir. ", "sourceLabel": "Gösterilen kaynak: 2023 Güz Vize · B Grubu · Soru 11 | Diğer kaynaklar: 2022 Final · B Grubu · arka sayfa · Soru 24. Şıklar gösterilen kaynağa aittir."}, {"id": "midterm-vize-2023-front-q12", "lesson": 101, "text": "Aşağıdakilerden hangisi bulut bilişimin avantajlarından değildir?", "options": ["Tasarruf", "Sınırsız Esneklik", "Zaman", "Sınırlı Kontrol", "Erişim Kolaylığı"], "answer": 3, "correctIndices": [3], "explanation": "Sınırlı kontrol dezavantajdır. Sınırsız esneklik ifadesi idealize ders ifadesidir; gerçek hizmetlerin sınırları vardır.", "sourceLabel": "Gösterilen kaynak: 2023 Güz Vize · B Grubu · Soru 12 | Diğer kaynaklar: 2022 Final · B Grubu · arka sayfa · Soru 22. Şıklar gösterilen kaynağa aittir."}, {"id": "midterm-vize-2023-front-q13", "lesson": 102, "text": "Aşağıdakilerden hangisi bulut bilişimin çözüm türlerinden değildir?", "options": ["Genel Bulut", "Özel Bulut", "Hibrit Bulut", "Topluluk Bulut", "Şirket Bulut"], "answer": 4, "correctIndices": [4], "explanation": "Notların dört dağıtım/çözüm türü genel, özel, hibrit ve topluluk bulutudur; şirket bulut ayrı beşinci standart model değildir. ", "sourceLabel": "Gösterilen kaynak: 2023 Güz Vize · B Grubu · Soru 13 | Diğer kaynaklar: 2024 Güz Vize · B Grubu · Soru 10 / 2024 Güz Vize · B Grubu · Soru 12. Şıklar gösterilen kaynağa aittir."}, {"id": "midterm-vize-2023-front-q14", "lesson": 101, "text": "Bulut bilişim tabanlı hizmet çözümlerini işletmelere ve bireylere sunan bir şirkete nedir?", "options": ["Servis Sağlayıcı", "Servis Geliştirici", "Tüketici", "Servis ağ hizmet sağlayıcı", "Üretici"], "answer": 0, "correctIndices": [0], "explanation": "Hizmet çözümlerini sunan kuruluş servis sağlayıcıdır. Sorunun sağ kenarı fotoğrafta kesilmiş; “işletmelere” kelimesinin sonu görünmüyor. “ne denir?” anlamı korunarak cümle düzenlendi.", "sourceLabel": "Gösterilen kaynak: 2023 Güz Vize · B Grubu · Soru 14"}, {"id": "midterm-vize-2024-q1", "lesson": 101, "text": "Bulut bilişimde veriler hangi ortamda depolanır?", "options": ["Yerel sunucularda", "Kullanıcı bilgisayarlarında", "İnternete bağlı uzak sunucularda", "Harici sabit disklerde", "USB belleklerde"], "answer": 2, "correctIndices": [2], "explanation": "Sorunun genel bulut bağlamında C beklenir: veri sağlayıcının ağ üzerinden erişilen sunucularında tutulur. Bulutun fiziksel sunucuları vardır. Özel bulut kurum içinde de barındırılabilir; bu şık her dağıtım modelini kapsayan katı fiziksel konum tanımı değildir.", "sourceLabel": "Gösterilen kaynak: 2024 Güz Vize · B Grubu · Soru 1"}, {"id": "midterm-vize-2024-q3", "lesson": 102, "text": "Bulut Bilişim Mimarisine göre SaaS’daki hangi yetki veya yetkileri vardır?", "options": ["Uygulamalar", "Uygulamalar, Veriler", "Yok", "Veri, Çalışma zamanı", "Uygulamalar, Veri, Çalışma zamanı"], "answer": 2, "correctIndices": [2], "explanation": "Dersin 2.3 PDF’sindeki Şekil 2.16 Bulut Bilişim Mimarisi tablosuna göre beklenen cevap C — Yok. SaaS sütununda uygulama, veri, çalışma zamanı ve alt katmanların işletimi “Provider manages” olarak gösterilir. Soru bu basitleştirilmiş katman yönetimi tablosuna göre çözülür. Bu, kullanıcının uygulamayı kullanma, verisini yönetme ve erişim izinleri konusunda hiçbir yetkisi olmadığı anlamına gelmez. Katmanların teknik işletimi ile müşterinin veri/erişim kararlarını ayır. Resmî sınav anahtarı mevcut değildir.", "sourceLabel": "Gösterilen kaynak: 2024 Güz Vize · B Grubu · Soru 3"}, {"id": "midterm-vize-2024-q4", "lesson": 102, "text": "Aşağıdaki bulut bilişim hizmet modellerinden hangisi yalnızca yazılım sunar?", "options": ["IaaS", "PaaS", "SaaS", "DaaS", "BaaS"], "answer": 2, "correctIndices": [2], "explanation": "Kullanıcıya hazır yazılım uygulaması sunan model SaaS’tır. “Yalnızca” müşteri açısından sunulan hazır uygulamayı anlatır; arka planda platform ve donanım bulunur. Diğer basım: 2024 Final klasörü, PHOTO-2026-10-28-15-27-20 2.jpg, Soru 4. Şıklar: . ", "sourceLabel": "Gösterilen kaynak: 2024 Güz Vize · B Grubu · Soru 4"}, {"id": "midterm-vize-2024-q5", "lesson": 101, "text": "Aşağıdakilerden hangisi bulut bilişimin işletmeler için maliyet avantajlarından biridir?", "options": ["Yüksek başlangıç yatırımı gerektirmesi", "Yalnızca kullanılan kaynak kadar ödeme yapılması", "Donanım ve yazılım altyapısına sahip olma zorunluluğu", "Kapsamlı bir güvenlik duvarı ihtiyacı", "Sürekli internet bağlantısına bağlı olması"], "answer": 1, "correctIndices": [1], "explanation": "Kullanılan/tahsis edilen kaynak ve hizmete göre ödeme, büyük peşin yatırım ihtiyacını azaltabilir. Gerçek faturalar hizmete göre abonelik, ayrılmış kapasite, istek ve aktarım gibi kalemler içerebilir; her hizmet tam aynı tüketim modeliyle ücretlenmez.", "sourceLabel": "Gösterilen kaynak: 2024 Güz Vize · B Grubu · Soru 5"}, {"id": "midterm-vize-2024-q6", "lesson": 101, "text": "Aşağıdakilerden hangisi bulut bilişimin dezavantajlarından değildir?", "options": ["Uyumluluk", "Sınırlı Kontrol", "Satıcı kilidi", "Planlı ve Plansız Kesintiler", "Yazılım Lisanslama"], "answer": 0, "correctIndices": [0], "explanation": "Notların olumlu uyumluluk/platform seçme imkânı sınıflandırmasında A beklenir. Diğer seçenekler kontrol, bağımlılık, süreklilik ve lisans riskleridir. Uyumluluk sorunları gerçek hayatta risk de olabilir; soruda avantaj başlığındaki “uyumluluk” anlamı kullanılıyor.", "sourceLabel": "Gösterilen kaynak: 2024 Güz Vize · B Grubu · Soru 6"}, {"id": "midterm-vize-2024-q7", "lesson": 103, "text": "Aşağıdakilerden hangisi ticari sanal makina yazılımlarına örnek verilemez?", "options": ["SVISTA", "Xen", "VMware", "Microsoft Virtual PC", "Parallels Workstation"], "answer": 1, "correctIndices": [1], "explanation": "Ders notlarının sınıflandırmasında Xen açık kaynak, diğer seçenekler ticari ürün örnekleridir. Bu tarihsel ürün/lisans sınıflandırmasıdır.", "sourceLabel": "Gösterilen kaynak: 2024 Güz Vize · B Grubu · Soru 7"}, {"id": "midterm-vize-2024-q8", "lesson": 101, "text": "“İsteğe bağlı, kendi kendine hizmet” ifadesi bulut bilişimde hangi kategori altında yer alır?", "options": ["Temel Unsurlar", "Hizmet Sunum Modelleri", "Konumlandırma Modelleri", "Özel Bulut", "Ortak kaynak havuzu"], "answer": 0, "correctIndices": [0], "explanation": "Kendi kendine hizmet beş temel bulut özelliğinden biridir; IaaS/PaaS/SaaS veya dağıtım modeli değildir.  Diğer basım: 2024 Final klasörü, PHOTO-2026-10-28-15-27-19.jpg, Soru 8. Şıklar: . ", "sourceLabel": "Gösterilen kaynak: 2024 Güz Vize · B Grubu · Soru 8"}, {"id": "midterm-vize-2024-q9", "lesson": 101, "text": "Bulut bilişimde yüksek kullanılabilirlik sağlamak için en önemli özellik nedir?", "options": ["Yüksek veri aktarım hızı", "İhtiyaç duyulan yazılımların kullanıcı tarafından yüklenmesi", "Verilerin dağınık veri merkezlerinde depolanması", "Yazılımların sürekli güncellenmesi", "Veritabanı yedekleme maliyetleri"], "answer": 2, "correctIndices": [2], "explanation": "Seçenekler içinde farklı arıza alanlarında veri/kaynak yedekliliği yüksek kullanılabilirliği destekler. Tek başına dosyaları dağıtmak kesintisizliği garanti etmez; kopyaların tutarlılığı, otomatik geçiş ve uygulama mimarisi de gerekir. Diğer basım: 2024 Final klasörü, PHOTO-2026-10-28-15-27-19.jpg, Soru 9. Şıklar: . ", "sourceLabel": "Gösterilen kaynak: 2024 Güz Vize · B Grubu · Soru 9"}, {"id": "midterm-vize-2024-q13", "lesson": 103, "text": "Sanallaştırma, aşağıdaki avantajlardan hangisini sağlayarak yazılım geliştirme ve test süreçlerini kolaylaştırır?", "options": ["Sunucu bakım maliyetlerinin artırılması", "Çok sayıda işletim sistemi lisansı alınması", "Gerektiğinde hızlıca yeni sanal sunucular oluşturabilme imkanı", "Fiziksel sunucuların yeniden yapılandırılması", "Sunucu ortamlarının sürekli olarak kapatılması"], "answer": 2, "correctIndices": [2], "explanation": "VM şablonları ve otomatik tahsisle geçici geliştirme/test ortamları hızlı oluşturulabilir; sonrasında kaldırılabilir. ", "sourceLabel": "Gösterilen kaynak: 2024 Güz Vize · B Grubu · Soru 13"}, {"id": "midterm-vize-2024-q14", "lesson": 103, "text": "Proses sanal sanallaştırma teknolojisine aşağıdakilerden hangisi örnek verilebilir?", "options": ["VMware", "Hyper-V", "Docker", ".NET", "VirtualBox"], "answer": 3, "correctIndices": [3], "explanation": ".NET çalışma zamanı (CLR) bir programın yürütülmesi için ortam sağlar; ders sınıflandırmasında proses sanal makinesi örneğidir. Docker işletim sistemi seviyesinde izolasyon/konteyner yaklaşımıdır; sistem VM yazılımlarıyla .NET çalışma zamanını karıştırma.", "sourceLabel": "Gösterilen kaynak: 2024 Güz Vize · B Grubu · Soru 14"}, {"id": "midterm-final-2022-front-q4", "lesson": 102, "text": "Aşağıdakilerden hangisi güncel bulut sistemlerinden değildir?", "options": ["Dropbox", "Microsoft Azure", "Amazon Web Services", "VMware"], "answer": 3, "correctIndices": [3], "explanation": "Sınavın kullandığı sınıflandırmada VMware sanallaştırma yazılım/teknoloji sağlayıcısı, diğerleri bulut hizmeti örnekleri olarak ele alınmış görünüyor. Tarihsel soru sınıflandırmasıdır. VMware’in bulutla ilişkili ürünleri/hizmetleri bulunduğu için “VMware bulut değildir” genellemesi teknik olarak yapılmamalıdır.", "sourceLabel": "Gösterilen kaynak: 2022 Güz Final · B Grubu · ön sayfa · Soru 4 | Diğer kaynaklar: 2023 Final · B Grubu · arka sayfa · Soru 20. Şıklar gösterilen kaynağa aittir."}, {"id": "midterm-final-2022-front-q5", "lesson": 102, "text": "En yaygın olarak kullanılan bulut servisi hangisidir?", "options": ["Simülasyon", "Veri yedekleme", "Sanallaştırma", "Kodlama işlemleri"], "answer": 1, "correctIndices": [1], "explanation": "Sorunun ders bağlamında beklediği örnek veri yedeklemedir. “En yaygın” ifadesi dönem/ölçüm belirtilmeden evrensel istatistik değildir; sınavın bağlamındaki yanıt olarak verilmiştir.", "sourceLabel": "Gösterilen kaynak: 2022 Güz Final · B Grubu · ön sayfa · Soru 5"}, {"id": "midterm-final-2022-front-q7", "lesson": 101, "text": "Aşağıdakilerden hangisi kamuda bulut bilişim kullanımına yönelik sorunlardandır?", "options": ["Yeşil teknoloji", "Küresel erişim", "Veri koruma ve uyum", "Basitlik"], "answer": 2, "correctIndices": [2], "explanation": "Veri koruma, gizlilik, veri konumu ve gereksinimlere uyum kamu bulutu kullanımında değerlendirilmesi gereken sorun alanlarıdır. ", "sourceLabel": "Gösterilen kaynak: 2022 Güz Final · B Grubu · ön sayfa · Soru 7 | Diğer kaynaklar: 2023 Final · B Grubu · arka sayfa · Soru 18. Şıklar gösterilen kaynağa aittir."}, {"id": "midterm-final-2022-front-q11", "lesson": 101, "text": "Aşağıdakilerden hangisi bulut bilişimin ekonomik yönden etkilerinden değildir?", "options": ["Enerji tasarrufları", "Karbon salınımlarında azalma", "Bireysel kullanım", "Üretkenliği artırma"], "answer": 2, "correctIndices": [2], "explanation": "Bireysel kullanım bir kullanım biçimidir; ekonomik/verimlilik etkisi olarak sayılan diğer maddelerden ayrılır. ", "sourceLabel": "Gösterilen kaynak: 2022 Güz Final · B Grubu · ön sayfa · Soru 11 | Diğer kaynaklar: 2023 Güz Final · B Grubu · ön sayfa · Soru 10. Şıklar gösterilen kaynağa aittir."}, {"id": "midterm-back-arka-q25", "lesson": 103, "text": "Aşağıdakilerden hangisi ticari sanal makina yazılımlarındandır?", "options": ["LilyVM", "QEMU", "SheepShaver", "VMware"], "answer": 3, "correctIndices": [3], "explanation": "Ders notlarındaki açık kaynak/ticari sınıflandırmada VMware ticari örnektir. ", "sourceLabel": "Gösterilen kaynak: 2022 Final · B Grubu · arka sayfa · Soru 25"}, {"id": "midterm-final-2023-front-q7", "lesson": 102, "text": "Şirketiniz tüm verilerini ve kaynaklarını Azure’a geçirmeyi planlıyor. Şirketin geçiş planında Azure’da yalnızca Hizmet Olarak Platform (PaaS) çözümlerinin kullanılması gerektiği belirtiliyor. Şirketin geçiş planını karşılayan bir Azure ortamı aşağıdakilerden hangisidir?", "options": ["Azure sanal makineleri, Azure SQL veritabanları ve Azure Depolama hesapları", "Microsoft SQL Server’ın yüklü olduğu bir Azure Uygulama Hizmeti ve Azure sanal makineleri", "Azure Uygulama Hizmeti ve Azure SQL veritabanları", "Azure sanal makinelerindeki Azure depolama hesapları ve web sunucusu", "Azure sanal makinelerindeki web sunucusu"], "answer": 2, "correctIndices": [2], "explanation": "Azure App Service ve Azure SQL Database yönetilen platform hizmetleridir. Diğer seçeneklerde sanal makine yönetimi (IaaS) bulunur. ", "sourceLabel": "Gösterilen kaynak: 2023 Güz Final · B Grubu · ön sayfa · Soru 7"}, {"id": "midterm-final-2023-front-q8", "lesson": 102, "text": "Azure Cosmo DB aşağıdakilerden hangisine bir örnektir?", "options": ["Servis Olarak Platform (PaaS)", "Servis Olarak Yazılım (SaaS)", "Servis Olarak Altyapı (IaaS)", "Servis Olarak Ortak (IaaO)", "Servis Olarak Veri (IaaD)"], "answer": 0, "correctIndices": [0], "explanation": "Azure Cosmos DB, yönetilen bir veri tabanı platform hizmeti olarak PaaS kapsamında değerlendirilir. Soruda “Cosmo DB” yazılmış; ürünün adı Cosmos DB’dir.", "sourceLabel": "Gösterilen kaynak: 2023 Güz Final · B Grubu · ön sayfa · Soru 8"}, {"id": "midterm-final-2023-front-q11", "lesson": 102, "text": "Altyapısını barındıran bir kuruluş, ………… artık bir veri merkezine ihtiyaç duymuyor. ………… yere aşağıdakilerden hangisi gelebilir?", "options": ["Özel bir bulutta", "Hibrit bir bulutta", "VM Makinalara", "Hyper-V ana bilgisayara", "Genel bulutta"], "answer": 4, "correctIndices": [4], "explanation": "Genel bulut hizmeti alındığında kurum kendi fiziksel veri merkezini işletmek zorunda kalmayabilir; fiziksel altyapıyı sağlayıcı işletir. Soru dilbilgisi bozuktur. Kurumun hiçbir yerel donanıma veya yönetim faaliyetine ihtiyacı kalmadığı anlamına gelmez.", "sourceLabel": "Gösterilen kaynak: 2023 Güz Final · B Grubu · ön sayfa · Soru 11"}, {"id": "midterm-back-arkaa-q24", "lesson": 101, "text": "Şirketinizde, şirketin tüm müşterilerinin kullandığı App1 adında bir muhasebe uygulaması bulunduğunu düşünürsek, App1’in kullanımı her ayın ilk üç haftasında düşük, son haftasında ise çok yüksek düzeyde ise bulut hizmetlerinin hangi avantajı bu tür kullanım düzeni için maliyet yönetimini destekler?", "options": ["Yüksek kullanılabilirlik", "Yüksek gecikme", "Esneklik", "Yük dengeleme", "Yük Dağıtma"], "answer": 2, "correctIndices": [2], "explanation": "Esneklik, kaynakları yoğun haftada artırıp diğer haftalarda azaltarak tüketimi talebe uyarlar. Yük dengeleme mevcut istekleri sunuculara dağıtır; aynı kavram değildir. ", "sourceLabel": "Gösterilen kaynak: 2023 Final · B Grubu · arka sayfa · Soru 24"}, {"id": "midterm-back-arkaa-q25", "lesson": 102, "text": "Genel bulutun özelliği hangisidir?", "options": ["Özel donanım", "Sınırlı depolama", "Güvenli olmayan bağlantılar", "Ölçülü fiyatlandırma", "Özel araçlar"], "answer": 3, "correctIndices": [3], "explanation": "Ölçülen kullanıma dayalı fiyatlandırma genel bulutun tipik özelliğidir. Özel donanım zorunlu bir özellik değildir. ", "sourceLabel": "Gösterilen kaynak: 2023 Final · B Grubu · arka sayfa · Soru 25"}];
